"""Product narrative generated from repository evidence, not new clinical claims."""
import html, json, re, shutil

IMPLANT_SVG = '''<svg class="implant-diagram" viewBox="0 0 560 520" role="img" aria-label="Simplified hip replacement schematic: socket, ball and stem, not a surgical guide">
<defs><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#f1fbff"/><stop offset=".45" stop-color="#748ba7"/><stop offset=".6" stop-color="#dcecff"/><stop offset="1" stop-color="#49667f"/></linearGradient><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#ffffff" stroke-opacity=".06"/></pattern></defs>
<rect width="560" height="520" fill="url(#grid)"/>
<g fill="none" stroke="#aab6c8" stroke-opacity=".3" stroke-width="24" stroke-linecap="round"><path d="M123 63Q238 42 275 139L290 181"/><path d="M281 225Q220 246 221 305L244 467M345 245Q372 301 331 464"/></g>
<g class="implant-part" data-part="socket"><path d="M231 151Q297 97 349 166L330 186Q292 144 251 180Z" fill="url(#metal)" stroke="#c5f6ec" stroke-width="2"/></g>
<g class="implant-part" data-part="ball"><circle cx="290" cy="200" r="34" fill="url(#metal)" stroke="#dcfff8" stroke-width="2"/></g>
<g class="implant-part" data-part="stem"><path d="M304 226L336 263 301 437Q292 449 285 435L269 294 256 272Z" fill="url(#metal)" stroke="#b0d0e6" stroke-width="2"/></g>
<g fill="none" stroke="#86e6ce" stroke-width="1"><path d="M337 150H413V116"/><path d="M256 198H130V215"/><path d="M315 334H418"/></g>
<g fill="#b9d1e3" font-family="system-ui" font-size="12"><text x="380" y="104">SOCKET / CUP</text><text x="73" y="239">BALL / HEAD</text><text x="429" y="339">STEM</text><text x="30" y="491" fill="#6b829c" font-size="10">ILLUSTRATIVE SCHEMATIC · HIP REPLACEMENT · NOT TO SCALE</text></g></svg>'''

def pages(page, head, sec, disc, root, data):
    out = {}
    context = head('01 / The context', 'Before the algorithm.<br><em>Understand the implant.</em>', 'Orthopaedic imaging AI starts with a real object, a real anatomy and a very specific question. Here is where our project fits.')
    context += sec('''<div class="context-grid"><div class="diagram-panel">''' + IMPLANT_SVG + '''</div><div><span class="eyebrow">A short introduction</span><h2>What is medical implantation?</h2><p class="lead">Implantation is the placement of a device or tissue in or on the body. Orthopaedic implants can replace joint surfaces or help support damaged bone.</p><p>A hip replacement typically includes a socket component, a ball and a stem. Knee and shoulder replacements have different shapes and components. These differences make radiographs useful for studying anatomy and implant appearance.</p><p class="source-note">Educational context: <a href="https://www.fda.gov/medical-devices/products-and-medical-procedures/implants-and-prosthetics" target="_blank" rel="noopener">FDA: implants and prosthetics ↗</a> · <a href="https://www.orthoinfo.org/treatment/joint-replacement/total-joint-replacement/" target="_blank" rel="noopener">AAOS: joint replacement ↗</a></p><div class="scope-note"><b>Our model names the joint.</b><p>It does not identify implant brands, recommend an implant, diagnose a condition or assess implant safety.</p></div></div></div>''')
    context += sec('''<span class="eyebrow">Three related questions. Three different tasks.</span><h2>Know what the output actually means.</h2><div class="task-grid"><article><span>01 / ANATOMY</span><h3>Which joint is this?</h3><p>Hip, Knee or Shoulder. This is the actual classification task in our checkpoints.</p><b class="badge built">Implemented here</b></article><article><span>02 / IMPLANT IDENTITY</span><h3>Which implant is present?</h3><p>Manufacturer, model or component identification is a separate task explored by existing implant-AI research.</p><b class="badge">Related work</b></article><article><span>03 / RELIABILITY</span><h3>Does the score transfer?</h3><p>Does joint recognition still work when the dataset source changes? This is our central evaluation question.</p><b class="badge built">Our study focus</b></article></div>''', 'tint')
    context += sec('''<div class="context-grid"><div><span class="eyebrow">Why implants appear in the story</span><h2>Source can become<br>a hidden answer key.</h2><p class="lead">The Kaggle hip source and UCI shoulder source contain implant radiographs. Other sources differ in age, framing, equipment and image properties.</p><p>When one source mostly corresponds to one joint, a network can exploit source-associated cues. Holding that source out tests a harder question. Implant presence is a plausible confound; this study does not show it causes the failures.</p><a class="btn primary" href="demo.html">See the checkpoints respond ↗</a><a class="btn" href="timeline.html" style="margin-top:12px">Explore implant history →</a></div><div class="source-map"><div><span>DATASET SOURCE</span><b>Acquisition style</b><b>Image dimensions</b><b>Implant appearance</b></div><span class="map-arrow">→</span><div><span>POTENTIAL SHORTCUT</span><b>Joint prediction</b><p>Looks successful in a pooled test.<br>May fail on an unfamiliar source.</p></div></div></div>''')
    context += sec(disc, 'tight')
    out['context.html'] = page('context.html','Implants & imaging','Understand orthopaedic implants, joint recognition and source-related shortcuts.',context)

    body = head('02 / Existing work → our contribution', 'Built on research.<br><em>Made inspectable.</em>', 'The contribution is a source-controlled evaluation and a working comparison tool—not a new implant-identification algorithm.')
    body += sec('''<div class="comparison-table tablewrap"><table class="data"><thead><tr><th>Dimension</th><th>What already exists</th><th>What this project adds</th></tr></thead><tbody>
<tr><td>Models</td><td>Random forests, EfficientNet-B3, Swin-T and ConvNeXt-T are established methods.</td><td>Controlled comparisons of these methods on one source-aware joint-recognition benchmark.</td></tr>
<tr><td>Application</td><td>Published systems investigate anatomy recognition and orthopaedic implant identification.</td><td>A narrower reliability question: how much does pooled evaluation overstate transfer to an unfamiliar source?</td></tr>
<tr><td>Evaluation</td><td>Shortcut learning and external validation are established research topics.</td><td>Six public sources, a multi-joint decoupled source, anatomy-free controls and paired saved predictions.</td></tr>
<tr><td>Demonstration</td><td>Single-model label/confidence displays are common interfaces.</td><td>Four actual checkpoints on the same input, source-held-out comparison, Grad-CAM and linked benchmark evidence.</td></tr>
<tr><td>Evidence</td><td>Dataset and architecture papers supply inputs and precedents.</td><td>Frozen analysis plan, grouped splits, checkpoint hashes, recorded deviations and independently checked saved metrics.</td></tr>
</tbody></table></div>''')
    body += sec('''<span class="eyebrow">The project evolved when the evidence changed</span><h2>From a high score<br>to a better question.</h2><ol class="evolution"><li><span>01</span><div><h3>Initial prototype</h3><p>Hip/Knee/Shoulder classification produced very high pooled scores. An audit showed labels were strongly tied to dataset source, so those scores could not establish anatomical generalization.</p></div></li><li><span>02</span><div><h3>Source-controlled study</h3><p>The project expanded to six sources and tested pooled, source-balanced, source-decoupled and held-out-source protocols, with simple non-anatomical controls.</p></div></li><li><span>03</span><div><h3>Integrated workbench</h3><p>The same study checkpoints now run on an uploaded image or held-out specimen. Predictions link to source sensitivity, uncertainty and the underlying evidence.</p></div></li><li><span>04</span><div><h3>Evaluation-ready evidence</h3><p>Automated checks, literature comparisons, a demo sequence and viva preparation make the system explainable and reviewable. Human validation and contribution evidence remain explicit gaps.</p></div></li></ol>''','tint')
    body += sec('''<div class="context-grid"><div><span class="eyebrow">Why it is useful</span><h2>A tool for asking<br>better evaluation questions.</h2><p class="lead">Students can explain an end-to-end ML system. Researchers can inspect how training-source changes affect the same image. Evaluators can follow a result back to a baseline and saved artifact.</p><p>The measured contribution is evidence of source sensitivity in this benchmark. We have not demonstrated clinical benefit, deployment at hospitals, cost savings or superiority to commercial implant systems.</p></div><div class="scope-note"><h3>What would strengthen it next?</h3><ul><li>Clinician verification of provisional knee labels.</li><li>Replication on another genuinely independent multi-joint source.</li><li>Broader training and domain-generalization comparisons.</li><li>Real user feedback, load tests and deployment validation.</li></ul><a href="limitations.html">Read the full limitations →</a></div></div>''')
    body += sec('<div class="inline-cta"><h2>Inspect what we built.</h2><a class="btn primary" href="demo.html">Launch the live workbench ↗</a><a class="btn" href="literature.html">Explore the literature →</a></div>'+disc,'tight')
    out['contribution.html']=page('contribution.html','Our contribution','Existing research, implemented modules, project evolution and bounded innovation.',body)

    refs=(root/'paper/sections/99_refs.md').read_text(encoding='utf-8')
    selected={1:'Shortcuts',2:'Shortcuts',4:'Shortcuts',5:'Shortcuts',6:'Generalization',7:'Generalization',8:'Generalization',9:'Anatomy',10:'Anatomy',11:'Anatomy',12:'Implants',13:'Implants',14:'Implants',15:'Generalization',17:'Implants',18:'Datasets',28:'Architecture'}
    cards=[]
    for line in refs.splitlines():
        match=re.match(r'(\d+)\. (.*)',line)
        if not match or int(match[1]) not in selected:continue
        num=int(match[1]);raw=match[2];theme=selected[num]
        doi=re.search(r'doi:(10\.[^\s;]+)',raw);arxiv=re.search(r'arXiv:(\d+\.\d+)',raw)
        url='https://doi.org/'+doi[1].rstrip('.') if doi else 'https://arxiv.org/abs/'+arxiv[1] if arxiv else ''
        reading='Full text recorded' if 'full text' in raw or '[C, F]' in raw else 'Page / metadata recorded' if 'page read' in raw else 'Abstract / metadata only'
        preprint='arXiv' in raw or 'medRxiv' in raw
        label='Preprint / version check' if preprint else 'Journal / proceedings record'
        clean=re.sub(r'\[[^]]*\]','',raw).replace('*','').strip()
        cards.append(f'<article class="paper-card" data-theme="{theme}" data-search="{html.escape(clean.lower(),quote=True)}"><div class="paper-top"><span>{theme}</span><span>REF {num:02}</span></div><h3>{html.escape(clean)}</h3><div class="paper-flags"><span>{reading}</span><span>{label}</span></div><a href="{html.escape(url)}" target="_blank" rel="noopener">View primary record ↗</a></article>')
    lit=head('Prior work and project evidence','Literature survey','Why we built OrthoTrace, how it compares with existing radiograph research, and what our results support.')
    lit+=sec('''<div id="prior-work-comparison"><h2>Why we built OrthoTrace</h2>
<p>When one dataset mostly contains one joint, a model can use image size, framing or other source clues to guess the joint. We built OrthoTrace to measure this effect and let reviewers inspect it on a single X-ray.</p>
<div class="tablewrap"><table><caption>Prior work and the OrthoTrace contribution</caption>
<thead><tr><th scope="col">Existing work</th><th scope="col">What it did</th><th scope="col">What OrthoTrace evaluates</th></tr></thead>
<tbody>
<tr><th scope="row"><a href="https://doi.org/10.1007/s00330-022-09184-6">SAM-X</a> and <a href="https://doi.org/10.1007/s00330-025-12053-7">Mitsuyama et al.</a></th><td>Radiograph anatomy classification, sorting and label quality.</td><td>How four checkpoints trained on different sources score the same image.</td></tr>
<tr><th scope="row"><a href="https://doi.org/10.1038/s41598-024-79838-6">Hill et al.</a> and <a href="https://doi.org/10.1038/s41746-024-01118-4">Ly et al.</a></th><td>Shortcut learning and acquisition bias in medical AI.</td><td>Dimensions-only controls, source holdouts and a paired border experiment.</td></tr>
<tr><th scope="row"><a href="https://doi.org/10.1038/s41597-023-02432-4">FracAtlas</a> and <a href="https://doi.org/10.1038/s41597-024-04311-y">BTXRD</a></th><td>Released radiographs for fracture and bone-tumor research.</td><td>Joint recognition under source change and a follow-up after investigating misclassifications.</td></tr>
<tr><th scope="row"><a href="https://doi.org/10.1148/ryai.2021200183">Patel et al.</a></th><td>Identified hip and knee implant models.</td><td>Whether joint recognition transfers when implant-image sources are unfamiliar.</td></tr>
</tbody></table></div>
<h3>What our results support</h3>
<ul><li>RBF SVM led the six classical classifiers on the 47-image FracAtlas validation holdout at <b>56.5% balanced accuracy</b>.</li>
<li>Center cropping raised Knee detections from <b>8 to 21 of 37</b> and reduced extra Elbow flags from <b>33 to 16 of 49</b> on the same 54 BTXRD images. This cohort informed the revision.</li>
<li>The workbench connects the model outputs to the original image, a Grad-CAM overlay and an exportable review record. Comparison with prior systems would require shared images, labels and metrics.</li></ul>
<h3>Research objectives and evidence</h3>
<ul><li>Measure transfer when FracAtlas is held out. <a href="results.html#t-gap">Source-controlled benchmark</a></li>
<li>Test whether dimensions and borders influence predictions. <a href="border-audit.html">Paired border experiment</a></li>
<li>Compare classical models using the same image features. <a href="methodology.html#algorithm-comparison">Algorithm comparison</a></li>
<li>Inspect prediction and label disagreements on individual images. <a href="demo.html?sample=6">Specimen 06</a></li></ul>
<p><a class="btn primary" href="downloads/literaturesurvey.md">Download the full literature survey</a> <a href="evaluation.html#external-check">View the BTXRD evidence</a></p>
</div>''')
    lit+=sec('''<div class="lit-summary"><div><b>17</b><span>recent bibliography entries organized</span></div><div><b>6</b><span>research themes</span></div><div><b>Open</b><span>full-text and venue checks remain</span></div></div><div class="scope-note"><b>Coverage is not the same as review completion.</b><p>Some entries are abstract-only or preprints. This page does not certify 15 fully reviewed recent journal/conference papers. Years and publication versions must be checked against the evaluator's five-year window.</p></div><div class="literature-tools"><label for="paper-search">Search the reading room<input id="paper-search" type="search" placeholder="Author, title, dataset…"></label><label for="paper-theme">Research theme<select id="paper-theme"><option value="all">All themes</option>'''+''.join(f'<option>{x}</option>' for x in sorted(set(selected.values())))+'''</select></label><p id="paper-count" aria-live="polite">17 references</p></div><div id="paper-list" class="paper-grid">'''+''.join(cards)+'''</div><p id="paper-empty" hidden>No references match. Try another term or choose All themes.</p>''')
    lit+=sec('''<span class="eyebrow">Critical synthesis</span><h2>Three lessons.<br>One focused research gap.</h2><div class="task-grid"><article><span>01 / SHORTCUTS</span><h3>High accuracy needs context.</h3><p>Shortcut research motivates testing non-anatomical information. Our dimension and metadata controls make that question measurable on this benchmark.</p></article><article><span>02 / VALIDATION</span><h3>Source separation matters.</h3><p>External-validation work motivates holding out sources. Our public-source comparison does not substitute for clinical hospital-level validation.</p></article><article><span>03 / TASK DEFINITION</span><h3>Related tasks are different.</h3><p>Implant identity, abnormality detection and joint recognition have different labels and datasets. Cross-paper accuracy rankings would be misleading.</p></article></div><div class="gap-statement"><span class="eyebrow">Our bounded gap</span><h3>How much does pooled public-data evaluation overstate hip, knee and shoulder recognition when joint and source are confounded?</h3><p>We address this question with six sources, anatomy-free baselines, multiple model families and source-controlled comparisons. We do not claim to have discovered shortcut learning or to be the first study of its kind.</p></div><a class="btn primary" href="downloads/LITERATURE_MATRIX.md">Download the critical comparison matrix ↗</a>''','tint')
    lit+=sec(disc,'tight')
    out['literature.html']=page('literature.html','Literature survey','Search 17 thematic bibliography entries and inspect the research gap and evidence limits.',lit,['showcase.js'])

    rows=[('Literature','Literature survey and coverage','Thematic survey, comparison table and research gap. Full-text and venue checks are still being completed by the team.','literature.html'),('Literature','Critical analysis and research gap','Prior-work comparison and a matched border-intervention experiment.','border-audit.html'),('Study','Problem formulation and relevance','Measurable H1 gap and source-decoupled evaluation.','research.html'),('Study','Methodology and design','Group-aware split, model pipeline, freeze and metrics.','methodology.html'),('Demo','Working end-to-end demo','Six-region inference, four benchmark checkpoints, a shortcut probe and an interactive paired border comparison.','demo.html'),('Demo','Industry relevance','Researcher and student use case; scaling, deployment and cost limits discussed.','contribution.html'),('Evaluation','Testing, metrics and results','Service tests, saved-result audit and baseline comparisons.','results.html'),('Evaluation','Objectives and innovation','Paired same-source and cross-source border controls implemented and measured.','border-audit.html'),('Report','Report and documentation','Manuscript, delivery notes and the project report.','paper.html'),('Report','Technical content across phases','Study reports, implementation, results, limitations and future work.','downloads/DELIVERY.md'),('Report','Citations and originality','Reference verification registry. A similarity check is run through the institution.','literature.html'),('Team','Contribution and Q&A preparation','Each member completes their own contribution form.','downloads/TEAM_CHECKLIST.md'),('Team','Demo and viva guide','Eight-minute presentation and technically grounded answers.','downloads/DEMO_AND_VIVA.md')]
    hub=head('04 / Evidence & evaluation','Every claim.<br><em>A place to check it.</em>','A review path through the actual implementation, study evidence and open items. Marks are awarded by the faculty; this page only points to evidence.')
    hub+=sec('''<div class="evidence-links"><a href="demo.html"><span>01 / EXPERIENCE</span><h3>Run the end-to-end demo ↗</h3><p>Image → six-region scores → four benchmark predictions → Grad-CAM.</p></a><a href="results.html"><span>02 / MEASURE</span><h3>Explore actual results ↗</h3><p>Balanced accuracy, baselines, intervals, source shift and reliability.</p></a><a href="border-audit.html"><span>RESEARCH EXTENSION</span><h3>Try the paired border audit ↗</h3><p>Compare three versions of the same held-out image and inspect the paired results.</p></a><a href="downloads/DEMO_AND_VIVA.md"><span>03 / EXPLAIN</span><h3>Follow the demo & viva guide ↗</h3><p>Eight-minute presentation and technically grounded answers.</p></a></div><div class="rubric-heading"><h2>Where each part is documented.</h2><p>Evidence is listed by area. Marks are awarded by the faculty, not by this project.</p></div><div class="tablewrap"><table class="data rubric-table"><thead><tr><th>Area</th><th>Topic</th><th>Evidence / next step</th></tr></thead><tbody>'''+''.join(f'<tr><td>{area}</td><td><a href="{link}">{title}</a></td><td>{detail}</td></tr>' for area,title,detail,link in rows)+'''</tbody></table></div>''')
    hub+=sec('''<div class="context-grid"><div><span class="eyebrow">Scientific evidence</span><h2>Results are reproducible.<br>Limits stay visible.</h2><p>Saved predictions independently reproduce 438 balanced-accuracy summary cells. All 29 study checkpoint hashes match the supplied registry. The live API reproduces the nine shipped sample outputs.</p><p>These checks support implementation integrity. They do not validate provisional knee labels, establish clinical performance or prove causal implant effects.</p><a class="btn" href="downloads/DELIVERY.md">Read the verification report →</a></div><div class="scope-note"><h3>What only the team can finish</h3><ul><li>Real contribution logs, challenges and lessons.</li><li>Department report format and signatures.</li><li>Clinician review and any required data agreements.</li><li>Full-text literature review and originality evidence.</li></ul></div></div>''','tint')
    btxrd = root / "artifacts/retraining/btxrd-mirror-evaluation.json"
    if btxrd.is_file():
        audit = json.loads(btxrd.read_text(encoding="utf-8"))
        counts = "".join(
            f'<tr><th scope="row">{html.escape(joint)}</th>'
            f'<td>{row["true_positives"]} of {row["positives"]}</td>'
            f'<td>{row["false_flags_on_other_joints"]} of {row["other_joint_images"]}</td></tr>'
            for joint, row in audit["summary"].items()
        )
        shutil.copy2(btxrd, root / "site/downloads" / btxrd.name)
        rerun = root / "artifacts/retraining/center-crop-candidates.json"
        followup = ""
        if rerun.is_file():
            candidate = json.loads(rerun.read_text(encoding="utf-8"))["center"]
            shutil.copy2(rerun, root / "site/downloads" / rerun.name)
            updated = "".join(
                f'<tr><th scope="row">{html.escape(joint)}</th><td>{row["true_positives"]} of {row["positives"]}</td>'
                f'<td>{row["false_flags_on_other_joints"]} of {row["other_joint_images"]}</td></tr>'
                for joint, row in candidate["external"].items()
            )
            followup = f"""<h3>After centering the input</h3>
<p>The revision trims 15% from each edge before applying the eight-view scoring method. Cutoffs were fitted on development validation data. The same 54 BTXRD images were rechecked after the baseline failure was inspected, so this is a follow-up comparison.</p>
<div class="tablewrap"><table><caption>BTXRD follow-up after center cropping</caption>
<thead><tr><th scope="col">Joint</th><th scope="col">Flagged on matching images</th><th scope="col">Flagged on other tagged images</th></tr></thead><tbody>{updated}</tbody></table></div>
<p><a href="downloads/{rerun.name}">Download the follow-up results</a></p>"""

        hub += sec(f"""<div id="external-check"><h2>Independent dataset check</h2>
<p>We froze the expanded model and its cutoffs before scoring {len(audit["predictions"])} BTXRD radiographs from the public mirror. Each image had exactly one of the three target joint tags.</p>
<div class="tablewrap"><table><caption>Model flags compared with BTXRD dataset tags</caption>
<thead><tr><th scope="col">Joint</th><th scope="col">Flagged on matching images</th><th scope="col">Flagged on other tagged images</th></tr></thead>
<tbody>{counts}</tbody></table></div>
<p>The Elbow output frequently appeared on images tagged Knee or Shoulder. The cohort contains only five elbow-tagged images. We used the published dataset tags and did not obtain a separate clinician review.</p>
<p><a href="downloads/{btxrd.name}">Download the per-image results</a> · <a href="https://doi.org/10.6084/m9.figshare.27865398">BTXRD dataset</a></p>{followup}</div>""")
    hub+=sec(disc,'tight')
    out['evaluation.html']=page('evaluation.html','Evaluation evidence','Where each part of the project is documented, with working demo evidence and honest open items.',hub)
    return out
